import Calligraphy
import Manuscript

struct Readme: StringComponent {

    let service: Service

    var body: some StringComponent {
        "# \(service.name)"
        Blank()
        "Generated by Quill. Do not edit."
        Blank()
        "## Types"
        ForEach(service.types) { type in
            "- `\(type.name)`"
        }
    }

}
